mapper.update:
UPDATE plate
   SET position_status = #{param3}, possible_locations = NULL
 WHERE tenant_id = #{param1} AND barcode = #{param2}

UPDATE device_state SET current_run_id = NULL, status = 'idle', updated_at = now()
 WHERE tenant_id = #{param1} AND current_run_id = #{param2}
   AND status <> 'running'

UPDATE run SET status = 'queued'::run_status, pause_kind = NULL,
       pause_reason = NULL, resumed_at = now(), updated_at = now()
 WHERE tenant_id = #{param1} AND id = #{param2}

UPDATE run SET status = 'aborted', pause_kind = NULL, pause_reason = NULL, pause_node_key = NULL, actual_end = now(), error_code = COALESCE(error_code, 'EC-HUMAN-DISMISS'), updated_at = now() WHERE tenant_id = #{tenantId} AND status = 'paused'
AND pause_kind = #{kind}
AND updated_at < now() - make_interval(hours => #{beforeHours})

UPDATE plate SET position_status = 'UNKNOWN',
       possible_locations = ARRAY#{i}
 WHERE tenant_id = #{tenantId} AND barcode = #{barcode}

UPDATE position_state
   SET reserved_by_run = -1, block_reason = 'PLATE_UNKNOWN',
       reserved_until = now() + interval '24 hours', updated_at = now()
 WHERE tenant_id = #{tenantId}
   AND resource_id IN #{i}
   AND plate_id IS NULL

UPDATE position_state
   SET reserved_by_run = NULL, block_reason = NULL,
       reserved_until = NULL, updated_at = now()
 WHERE tenant_id = #{tenantId}
   AND resource_id IN #{i}
   AND block_reason = 'PLATE_UNKNOWN'

mapper.select:
SELECT count(*) FROM transfer_transaction
 WHERE tenant_id = #{param1} AND run_id = #{param2}
   AND status IN ('REPORTED', 'UNKNOWN')

SELECT a.id AS "id", a.barcode AS "barcode",
       a.from_status AS "fromStatus", a.to_status AS "toStatus",
       a.actual_location AS "actualLocation",
       a.operator AS "operator", a.note AS "note",
       a.run_id AS "runId", a.created_at AS "createdAt"
  FROM plate_location_audit a
 WHERE a.tenant_id = #{tenantId}

   AND a.barcode = #{barcode}

 ORDER BY a.created_at DESC, a.id DESC
 LIMIT #{limit}

mapper.update:
UPDATE pause_request SET result_state = #{resultState},
       result_detail = #{resultDetail, jdbcType=VARCHAR}
 WHERE tenant_id = #{tenantId} AND request_id = #{requestId}
